<?php

namespace App\Filament\Resources\Expenses\Schemas;

use App\Models\Cashbox;
use Filament\Forms\Components;
use Filament\Schemas\Schema;

class ExpenseForm
{
    public static function configure(Schema $schema): Schema
    {
        return $schema
            ->components([
                // expense_number is generated by GeneratesDocumentCode
                Components\Select::make('expense_category_id')
                    ->label(__('erp.resources.expense_category'))
                    ->relationship('category', 'name')
                    ->searchable()
                    ->preload()
                    ->required(),
                Components\Select::make('cashbox_id')
                    ->label(__('erp.fields.disbursing_cashbox'))
                    ->relationship('cashbox', 'name', fn ($query) => $query->where('is_active', true))
                    ->default(fn () => Cashbox::where('is_active', true)->orderBy('id')->value('id'))
                    ->searchable()
                    ->preload()
                    ->required(),
                Components\TextInput::make('amount')
                    ->label(__('erp.fields.amount'))
                    ->numeric()
                    ->minValue(0.01)
                    ->prefix('EGP')
                    ->required(),
                Components\DatePicker::make('expense_date')
                    ->label(__('erp.fields.payment_date'))
                    ->default(now())
                    ->required(),
                Components\TextInput::make('reference_number')
                    ->label(__('erp.fields.reference_number'))
                    ->maxLength(100),
                Components\Textarea::make('notes')
                    ->label(__('erp.fields.description'))
                    ->columnSpanFull(),
            ]);
    }
}
